CREATE TABLE IF NOT EXISTS chat_notification_preferences (user_id TEXT PRIMARY KEY REFERENCES people(id), auth_version INTEGER NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, enabled_at INTEGER NOT NULL, quiet_start INTEGER NOT NULL DEFAULT 1320, quiet_end INTEGER NOT NULL DEFAULT 420, quiet_enabled INTEGER NOT NULL DEFAULT 0, timezone TEXT NOT NULL DEFAULT 'UTC', muted_rooms TEXT NOT NULL DEFAULT '[]', last_attempt INTEGER NOT NULL DEFAULT 0, lease_until INTEGER NOT NULL DEFAULT 0, lease_token TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS chat_push_receipts (device_id TEXT NOT NULL REFERENCES push_devices(id) ON DELETE CASCADE, message_id TEXT NOT NULL REFERENCES messages(id), created_at INTEGER NOT NULL, PRIMARY KEY(device_id,message_id));
CREATE TABLE IF NOT EXISTS employee_status (user_id TEXT PRIMARY KEY REFERENCES people(id), status TEXT NOT NULL CHECK(status IN ('available','working','away','driving')), expires_at INTEGER NOT NULL, auth_version INTEGER NOT NULL);
